CREATE TABLE IF NOT EXISTS finora_users (id VARCHAR(64) PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, currency VARCHAR(12) NOT NULL DEFAULT 'INR', monthly_income DECIMAL(15,2) NOT NULL DEFAULT 0, avatar VARCHAR(8) NOT NULL DEFAULT 'AM', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS finora_states (user_id VARCHAR(64) PRIMARY KEY, payload JSON NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT finora_states_user_fk FOREIGN KEY (user_id) REFERENCES finora_users(id) ON DELETE CASCADE);
